questionvariables.text:
listmin(l) := apply(min, l);
rot(p, th) := [p[1]*cos(th) - p[2]*sin(th), p[1]*sin(th) + p[2]*cos(th)];
placeRight(pts) := block([xs, ys, tx, ty],
    xs : map(first, pts), ys : map(second, pts),
    tx : 7 - listmin(xs), ty : 0 - listmin(ys),
    map(lambda([p], [p[1] + tx, p[2] + ty]), pts));
/* fl = 1 keeps orientation, fl = -1 reflects (flips) the triangle before rotating */
rigid(pts, th, fl) := map(lambda([p], rot([p[1], fl*p[2]], th)), pts);
scaleRot(pts, k, th, fl) := map(lambda([p], rot([k*p[1], fl*k*p[2]], th)), pts);

/* base triangles (both listed counter-clockwise) */
Vbase  : [[0, 0], [4.4, 0], [0.9, 2.9]];   /* scalene */
Vright : [[0, 0], [4.0, 0], [0, 3.0]];     /* right angle at vertex 0 */

/* orientation of the second (copied) triangle */
th : float(rand([%pi/9, %pi/6, 2*%pi/9, 5*%pi/18, %pi/3, 7*%pi/18, 4*%pi/9, 5*%pi/9, 11*%pi/18, 2*%pi/3]));

/* fl = -1 makes the copy a flipped (reflected) as well as rotated version */
fl : rand([1, -1]);

/* choose one of 7 marking cases */
cs : rand(7) + 1;

/* defaults (used by cases 1-4) */
V1 : Vbase;
V2 : placeRight(rigid(Vbase, th, fl));
st1 : [0, 0, 0]; st2 : [0, 0, 0];
aa1 : [0, 0, 0]; aa2 : [0, 0, 0];
ansval : "SSS"; ansdisp : "SSS";
casewhy : "";

if cs = 1 then (
    st1 : [1, 2, 3], st2 : [1, 2, 3],
    ansval : "SSS", ansdisp : "SSS (Side-Side-Side)",
    casewhy : "All three pairs of corresponding sides are marked equal, so the triangles are congruent by SSS."
) elseif cs = 2 then (
    /* SAS: two sides (opposite B and C) with the included angle at A */
    st1 : [0, 1, 2], st2 : [0, 1, 2],
    aa1 : [1, 0, 0], aa2 : [1, 0, 0],
    ansval : "SAS", ansdisp : "SAS (Side-Angle-Side)",
    casewhy : "Two pairs of sides are equal and the angle between them (the included angle) is equal, so the triangles are congruent by SAS."
) elseif cs = 3 then (
    /* ASA: angles at A and B with the included side AB (opposite C) */
    st1 : [0, 0, 1], st2 : [0, 0, 1],
    aa1 : [1, 2, 0], aa2 : [1, 2, 0],
    ansval : "ASA", ansdisp : "ASA (Angle-Side-Angle)",
    casewhy : "Two pairs of angles are equal and the side between them (the included side) is equal, so the triangles are congruent by ASA."
) elseif cs = 4 then (
    /* AAS: angles at A and B with a non-included side AC (opposite B) */
    st1 : [0, 1, 0], st2 : [0, 1, 0],
    aa1 : [1, 2, 0], aa2 : [1, 2, 0],
    ansval : "AAS", ansdisp : "AAS (Angle-Angle-Side)",
    casewhy : "Two pairs of angles are equal and a pair of corresponding sides that is not between them is equal, so the triangles are congruent by AAS."
) elseif cs = 5 then (
    /* RHS: right angle at A, equal hypotenuse (opposite A) and one leg AB (opposite C) */
    V1 : Vright,
    V2 : placeRight(rigid(Vright, th, fl)),
    st1 : [1, 0, 2], st2 : [1, 0, 2],
    aa1 : [4, 0, 0], aa2 : [4, 0, 0],
    ansval : "RHS", ansdisp : "RHS (Right angle-Hypotenuse-Side)",
    casewhy : "Both triangles have a right angle, an equal hypotenuse and one equal shorter side, so they are congruent by RHS."
) elseif cs = 6 then (
    /* AAA: equiangular but the second triangle is shrunk - similar, not congruent */
    V2 : placeRight(scaleRot(Vbase, 0.9, th, fl)),
    aa1 : [1, 2, 3], aa2 : [1, 2, 3],
    ansval : "NONE", ansdisp : "Not necessarily congruent (only similar)",
    casewhy : "Only the three angles are marked equal (AAA). Equal angles guarantee the same shape but not the same size, so the triangles are similar, not necessarily congruent."
) else (
    /* SSA: two sides and a non-included angle - the ambiguous case */
    V1 : [[0, 0], [5, 0], [4.789, 2.992]],
    V2 : placeRight([[0, 0], [5, 0], [2.401, 1.5]]),
    st1 : [2, 0, 1], st2 : [2, 0, 1],
    aa1 : [1, 0, 0], aa2 : [1, 0, 0],
    ansval : "NONE", ansdisp : "Not necessarily congruent (ambiguous SSA case)",
    casewhy : "Two sides and a non-included angle (SSA) are marked equal. This does not fix a unique triangle - the same two sides and angle can form two different triangles - so they are not necessarily congruent."
);

V1 : float(V1);
V2 : float(V2);

/* dropdown options: [value, correct?, displayed label] */
opts : [["SSS", is(ansval = "SSS"), "SSS (Side-Side-Side)"],
        ["SAS", is(ansval = "SAS"), "SAS (Side-Angle-Side)"],
        ["ASA", is(ansval = "ASA"), "ASA (Angle-Side-Angle)"],
        ["AAS", is(ansval = "AAS"), "AAS (Angle-Angle-Side)"],
        ["RHS", is(ansval = "RHS"), "RHS (Right angle-Hypotenuse-Side)"],
        ["NONE", is(ansval = "NONE"), "Not necessarily congruent"]];
ta : random_permutation(opts);
correctv : mcq_correct(ta)[1];
